INSERT INTO events ("id", "title", "description", "category", "start_time", "end_time", "created_by", "max_participants", "created_at", "image_url", "status", "location", "time_display", "date_display") VALUES ('evt_poetry_night', 'أمسية الفضفضة الكبرى: سهرة أدبية وشعرية', 'لقاء صوتي وحواري مميز يجمع رواد فضفضه لمشاركة أجمل الأبيات الشعرية والنصوص الأدبية، مع مسابقات فورية وتوزيع جوائز وهدايا كوينز لجميع الحاضرين.', 'مجالس شعر وأدب', '2026-10-15 21:00:00', '2026-10-15 23:30:00', 'usr_1790285919516_kn7t3', 250, '2026-10-03 21:55:04', 'https://images.unsplash.com/photo-1519791883288-dc8bd696e667?auto=format&fit=crop&w=1200&q=80', 'upcoming', 'مجلس ديوان العرب (صوتي)', '09:00 م', '15 أكتوبر 2026') ON CONFLICT DO NOTHING;
INSERT INTO events ("id", "title", "description", "category", "start_time", "end_time", "created_by", "max_participants", "created_at", "image_url", "status", "location", "time_display", "date_display") VALUES ('evt_proverbs_quiz', 'بطولة الأمثال وتحدي المعرفة الموسمية', 'تحدي جماعي حماسي في لعبة الأمثال الشعبية والألغاز التراثية. يتنافس فيها الأعضاء في جولات سريعة للفوز بلقب بطل الفضفضة وشارة حصرية وجوائز كبرى من الكوينز.', 'ألعاب ومسابقات', '2026-10-22 20:30:00', '2026-10-22 22:30:00', 'usr_1790285919516_kn7t3', 150, '2026-10-03 21:55:04', 'https://images.unsplash.com/photo-1511512578047-dfb367046420?auto=format&fit=crop&w=1200&q=80', 'upcoming', 'صالة الألعاب والتحديات الكبرى', '08:30 م', '22 أكتوبر 2026') ON CONFLICT DO NOTHING;
INSERT INTO events ("id", "title", "description", "category", "start_time", "end_time", "created_by", "max_participants", "created_at", "image_url", "status", "location", "time_display", "date_display") VALUES ('evt_mental_health', 'حلقة نقاش: فن الاستماع الإيجابي والتعبير الواعي', 'مساحة دافئة وآمنة للحديث حول إدارة ضغوط الحياة وأهمية التعبير عن المشاعر بوعي وإيجابية، بمشاركة نخبة من الأعضاء المهتمين بالإرشاد والدعم الإنساني.', 'تطوير ودعم نفسي', '2026-10-29 19:30:00', '2026-10-29 21:30:00', 'usr_1790285919516_kn7t3', 120, '2026-10-03 21:55:04', 'https://images.unsplash.com/photo-1529156069898-49953e39b3ac?auto=format&fit=crop&w=1200&q=80', 'upcoming', 'غرفة الدعم والاستماع الهادئ', '07:30 م', '29 أكتوبر 2026') ON CONFLICT DO NOTHING;
INSERT INTO events ("id", "title", "description", "category", "start_time", "end_time", "created_by", "max_participants", "created_at", "image_url", "status", "location", "time_display", "date_display") VALUES ('evt_past_celebration', 'حفل تدشين فضفضه السنوي وتكريم الأوائل', 'احتفلنا معاً بتدشين المزايا الجديدة للمنصة وتكريم أصحاب أعلى شعلات ونقاط خبرة خلال الموسم، مع توزيع أوسمة تذكارية لأكثر من 500 عضو.', 'احتفال وتكريم', '2026-09-20 21:00:00', '2026-09-20 23:00:00', 'usr_1790285919516_kn7t3', 500, '2026-10-03 21:55:04', 'https://images.unsplash.com/photo-1492684223066-81342ee5ff30?auto=format&fit=crop&w=1200&q=80', 'completed', 'المجلس الملكي العام', '09:00 م', '20 سبتمبر 2026') ON CONFLICT DO NOTHING;
INSERT INTO events ("id", "title", "description", "category", "start_time", "end_time", "created_by", "max_participants", "created_at", "image_url", "status", "location", "time_display", "date_display") VALUES ('evt_past_podcast', 'ليلة البودكاست: تجارب وقصص غيرت حياة أصحابها', 'استمعنا في أجواء حميمة لعشرات القصص الملهمة التي رواها أعضاء فضفضه بكل شجاعة وصدق، وحظيت الأمسية بتفاعل استثنائي تجاوز 300 مشارك.', 'قصص وتجارب', '2026-09-05 20:00:00', '2026-09-05 22:00:00', 'usr_1790285919516_kn7t3', 300, '2026-10-03 21:55:04', 'https://images.unsplash.com/photo-1478737270239-2f02b77fc618?auto=format&fit=crop&w=1200&q=80', 'completed', 'مجلس القصص والحكايات', '08:00 م', '05 سبتمبر 2026') ON CONFLICT DO NOTHING;
